import re
with open('theory_draft.tex') as f:
    lines = f.readlines()

stack = []
for i, line in enumerate(lines, 1):
    for m in re.finditer(r'\\\\begin\{(\w+)\}', line):
        stack.append((m.group(1), i))
    for m in re.finditer(r'\\\\end\{(\w+)\}', line):
        env = m.group(1)
        if stack and stack[-1][0] == env:
            stack.pop()
        else:
            print(f'MISMATCH at line {i}: \\end{{{env}}} but stack top is {stack[-1] if stack else \"empty\"}')

if stack:
    print(f'UNCLOSED: {stack}')
else:
    print('All environments properly matched.')
"
